'use client'

import { marked } from 'marked'
import type { ReactNode } from 'react'
import { useUpdates } from '../../hooks/useUpdates'
import type { UpdateFeedItem } from '../../hooks/useUpdates'

export interface UpdatesFeedTranslations {
	loadingLabel: string
	emptyMessage: string
}

export interface UpdatesFeedProps {
	/** Slug of the update list to render. */
	listSlug: string
	/** Max items to fetch. Clamped server-side to 1..100; defaults to 20. */
	limit?: number
	className?: string
	/** Bring your own item renderer. Omit for the default title/image/date/body card. */
	renderItem?: (item: UpdateFeedItem) => ReactNode
	/** Locale for date formatting. Defaults to the visitor's locale. */
	locale?: string
	translations?: UpdatesFeedTranslations
}

const DEFAULT_TRANSLATIONS: UpdatesFeedTranslations = {
	loadingLabel: 'Loading updates…',
	emptyMessage: 'No updates yet.',
}

/** Event date wins over publish date — that is the date the reader cares about. */
function displayDate(item: UpdateFeedItem): string | null {
	return item.eventDate ?? item.publishedAt
}

function formatDate(value: string, locale?: string): string {
	return new Date(value).toLocaleDateString(locale, {
		year: 'numeric',
		month: 'long',
		day: 'numeric',
	})
}

/**
 * Renders one published update list. The body is markdown, rendered with
 * `marked` — the same renderer `BlogContent` and `NewsletterContent` already
 * use, so a client site styling `.prose` gets consistent output everywhere.
 */
export function UpdatesFeed({
	listSlug,
	limit,
	className,
	renderItem,
	locale,
	translations,
}: UpdatesFeedProps) {
	const { items, list, loading, error } = useUpdates(
		listSlug,
		limit !== undefined ? { limit } : undefined,
	)
	const t = translations ?? DEFAULT_TRANSLATIONS

	if (error) {
		return (
			<section className={className} aria-label={list?.name ?? 'Updates'}>
				<p className="text-error" role="alert">
					{error}
				</p>
			</section>
		)
	}

	return (
		<section className={className} aria-label={list?.name ?? 'Updates'} aria-busy={loading}>
			{loading && <p className="text-base-content/50">{t.loadingLabel}</p>}

			{!loading && items.length === 0 && (
				<p className="text-base-content/50">{t.emptyMessage}</p>
			)}

			{items.length > 0 && (
				<ul className="flex flex-col gap-8 list-none p-0 m-0">
					{items.map((item) => (
						<li key={item.id}>
							{renderItem ? renderItem(item) : <UpdateItemCard item={item} locale={locale} />}
						</li>
					))}
				</ul>
			)}
		</section>
	)
}

function UpdateItemCard({ item, locale }: { item: UpdateFeedItem; locale?: string | undefined }) {
	const date = displayDate(item)

	return (
		<article>
			{item.imageUrl && (
				<figure className="aspect-video overflow-hidden mb-3">
					<img src={item.imageUrl} alt={item.title} className="w-full h-full object-cover" />
				</figure>
			)}
			<h3 className="text-xl font-semibold">{item.title}</h3>
			{date && (
				<time className="text-sm text-base-content/50" dateTime={new Date(date).toISOString()}>
					{formatDate(date, locale)}
				</time>
			)}
			{item.body && (
				<div
					className="prose max-w-none mt-2"
					dangerouslySetInnerHTML={{
						__html: marked.parse(item.body, { async: false }) as string,
					}}
				/>
			)}
		</article>
	)
}
