'use client'

import { useState } from 'react'
import { subscribeToNewsletter } from '../../hooks/useNewsletter'

export interface NewsletterSignupProps {
	title?: string | undefined
	description?: string | undefined
	buttonLabel?: string | undefined
	placeholder?: string | undefined
	namePlaceholder?: string | undefined
	collectName?: boolean | undefined
	successMessage?: string | undefined
	className?: string | undefined
	onSuccess?: ((email: string) => void) | undefined
}

export function NewsletterSignup({
	title = 'Subscribe to our newsletter',
	description,
	buttonLabel = 'Subscribe',
	placeholder = 'you@example.com',
	namePlaceholder = 'Your name',
	collectName = false,
	successMessage = 'Thanks for subscribing!',
	className,
	onSuccess,
}: NewsletterSignupProps) {
	const [email, setEmail] = useState('')
	const [name, setName] = useState('')
	const [submitting, setSubmitting] = useState(false)
	const [subscribed, setSubscribed] = useState(false)
	const [error, setError] = useState('')

	async function handleSubmit(e: React.FormEvent) {
		e.preventDefault()
		setError('')
		setSubmitting(true)

		try {
			const result = await subscribeToNewsletter({
				email,
				...(collectName && name.trim() ? { name: name.trim() } : {}),
			})
			if (!result.ok) {
				setError(result.error ?? 'Something went wrong. Please try again.')
				return
			}
			setSubscribed(true)
			onSuccess?.(email)
		} catch {
			setError('Failed to subscribe. Please try again.')
		} finally {
			setSubmitting(false)
		}
	}

	if (subscribed) {
		return (
			<div className={`rounded-xl border bg-base-100 p-6 text-center ${className ?? ''}`.trim()}>
				<div className="mx-auto mb-3 flex h-10 w-10 items-center justify-center rounded-full bg-success/20">
					<svg className="h-5 w-5 text-success" fill="none" viewBox="0 0 24 24" stroke="currentColor">
						<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
					</svg>
				</div>
				<p className="font-semibold">{successMessage}</p>
			</div>
		)
	}

	return (
		<div className={`rounded-xl border bg-base-100 p-6 ${className ?? ''}`.trim()}>
			{title && <h2 className="text-xl font-semibold">{title}</h2>}
			{description && <p className="mt-1 text-base-content/60">{description}</p>}

			<form onSubmit={handleSubmit} className="mt-4 space-y-3">
				{collectName && (
					<input
						type="text"
						value={name}
						onChange={(e) => setName(e.target.value)}
						placeholder={namePlaceholder}
						aria-label={namePlaceholder}
						className="input input-bordered w-full"
					/>
				)}

				<input
					type="email"
					required
					value={email}
					onChange={(e) => setEmail(e.target.value)}
					placeholder={placeholder}
					aria-label="Email address"
					className="input input-bordered w-full"
				/>

				{error && <p className="text-sm text-error">{error}</p>}

				<button type="submit" disabled={submitting} className="btn btn-primary w-full">
					{submitting ? 'Subscribing...' : buttonLabel}
				</button>
			</form>
		</div>
	)
}
