import { marked } from 'marked'

/** Minimal, public-safe issue shape this component needs to render. */
export interface NewsletterContentIssue {
	subject: string
	/** Markdown source. */
	content: string
	sentAt: Date | string | null
	previewText?: string | null
}

export interface NewsletterContentProps {
	issue: NewsletterContentIssue
	/** Pre-localized sent date. Falls back to a plain date string when omitted. */
	date?: string | undefined
}

export function NewsletterContent({ issue, date }: NewsletterContentProps) {
	const displayDate =
		date ?? (issue.sentAt ? new Date(issue.sentAt).toLocaleDateString() : null)

	return (
		<article>
			<h1 className="text-4xl font-bold mb-2">{issue.subject}</h1>
			{displayDate && <time className="text-sm text-base-content/50">{displayDate}</time>}
			<div
				className="prose prose-lg max-w-none mt-6"
				dangerouslySetInnerHTML={{
					__html: marked.parse(issue.content, { async: false }) as string,
				}}
			/>
		</article>
	)
}
